cy.intercept('POST', '/api/cars').as('createCar');
_GaragePage.default.clickAddCar();
_GaragePage.default.selectBrand('Audi');
_GaragePage.default.selectModel('TT');
_GaragePage.default.setMileage('10000');
_GaragePage.default.submitAddCar();
cy.wait('@createCar').then(interception => {
  expect(interception.response.statusCode).to.eq(201);
  const carId = interception.response.body.data.id;
  cy.wrap(carId).as('carId');
});
cy.get('@carId').then(carId => {
  cy.getCookies().then(cookies => {
    const cookieString = cookies.map(c => `${c.name}=${c.value}`).join('; ');
    cy.request({
      method: 'GET',
      url: '/api/cars',
      headers: {
        Cookie: cookieString
      }
    }).then(response => {
      expect(response.status).to.eq(200);
      const cars = response.body.data;
      const createdCar = cars.find(car => car.id === carId);
      expect(createdCar).to.exist;
      expect(createdCar.brand).to.eq('Audi');
      expect(createdCar.model).to.eq('TT');
      expect(createdCar.initialMileage).to.eq(10000);
    });
  });
});

